package mx.portaltransporte.records;

import java.util.*;
import mx.portaltransporte.domain.*;
import mx.portaltransporte.domain.factory.ClientHistoryFactory;
import mx.portaltransporte.domain.factory.ClientRecordFactory;
import mx.portaltransporte.domain.factory.ClientVehicleFactory;
import mx.portaltransporte.domain.factory.VehicleFactory;
import mx.portaltransporte.domain.factory.VehiclePhotoFactory;
import mx.portaltransporte.domain.factory.WorkshopStatusFactory;
import mx.portaltransporte.repository.*;
import org.springframework.web.multipart.MultipartFile;
import mx.portaltransporte.security.CryptoService;
import io.micrometer.observation.annotation.Observed;
import org.springframework.cache.annotation.CacheEvict;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service @Transactional
@Observed(name = "service.records")
public class RecordService {
  private final ClientRecordRepository clients; private final VehicleRepository vehicles; private final UserAccountRepository users; private final CryptoService crypto; private final WorkshopRepository workshopRepo;
  private final ClientHistoryRepository history; private final ClientVehicleRepository links; private final WorkshopStatusRepository statuses; private final VehiclePhotoRepository vehiclePhotos;
  private final ClientRowsCache rows;
  private final ClientRecordFactory clientFactory = new ClientRecordFactory();
  private final VehicleFactory vehicleFactory = new VehicleFactory();
  private final VehiclePhotoFactory vehiclePhotoFactory = new VehiclePhotoFactory();
  private final ClientHistoryFactory historyFactory = new ClientHistoryFactory();
  private final ClientVehicleFactory linkFactory = new ClientVehicleFactory();
  private final WorkshopStatusFactory statusFactory = new WorkshopStatusFactory();
  // Guarda dependencias. Actor: sistema. Tecnica: inyeccion por constructor.
  public RecordService(ClientRecordRepository clients,VehicleRepository vehicles,UserAccountRepository users,CryptoService crypto,WorkshopRepository workshopRepo,ClientHistoryRepository history,ClientVehicleRepository links,WorkshopStatusRepository statuses,VehiclePhotoRepository vehiclePhotos,ClientRowsCache rows) { this.clients=clients; this.vehicles=vehicles; this.users=users; this.crypto=crypto; this.workshopRepo=workshopRepo; this.history=history; this.links=links; this.statuses=statuses; this.vehiclePhotos=vehiclePhotos; this.rows=rows; }
  // Crea cliente UC-CV-01 con principal, secundarios y taller activo. Actor: ADMINISTRADOR o RECEPCIONISTA. Tecnica: nace ACTIVO y audita CREADO.
  @CacheEvict(value="clientRows",allEntries=true)
  public UUID createClient(RecordDtos.CreateClientRequest request, String actorId) { UserAccount actor=users.findById(UUID.fromString(actorId)).orElseThrow(() -> new ResponseStatusException(HttpStatus.UNAUTHORIZED)); var name=crypto.encrypt(request.name().trim()); ClientRecord client=clientFactory.create(new ClientRecordFactory.ClientParams(RecordPolicy.PERSON_TYPE,name.value(),name.nonce(),actor)); client.setStatus(activeStatus()); var document=crypto.encrypt(normalizeDocument(request.document())); try { client.addIdentification(RecordPolicy.OTHER_TYPE,crypto.lookup(request.document()),document.value(),document.nonce()); } catch (Exception duplicate) { throw new ResponseStatusException(HttpStatus.CONFLICT,"Client already exists"); } java.util.List<String> unique=normalizeContacts(request.contacts(),request.email()); if (unique.isEmpty()) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"At least one contact is required"); storePrincipal(client,unique.get(0)); storeSecondaries(client,request.secondaryContacts()); client.setWorkshop(resolveWorkshop(request.workshopId())); try { ClientRecord saved=clients.save(client); audit(saved,RecordPolicy.HISTORY_CREATED,"Alta con "+contactCount(saved)+" contacto(s)",actor); return saved.getId(); } catch (org.springframework.dao.DataIntegrityViolationException duplicate) { throw new ResponseStatusException(HttpStatus.CONFLICT,"Client already exists"); } }
  // Pagina validada de clientes. Actor: rol autorizado. Tecnica: pagina base 1, 10 registros, recorte del cache.
  public RecordDtos.ClientPageResponse listClients(int page, int size, boolean onlyActive) { if (page<RecordPolicy.CLIENT_PAGE_MIN) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid page"); if (size<1||size>RecordPolicy.CLIENT_PAGE_SIZE_MAX) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid size"); List<RecordDtos.ClientResponse> all=rows.all(onlyActive); int total=all.size(); int totalPages=total==0?0:(int) Math.ceil((double) total/size); int from=(page-1)*size; List<RecordDtos.ClientResponse> content=from>=total?List.of():all.subList(from,Math.min(from+size,total)); return new RecordDtos.ClientPageResponse(content,page,size,total,totalPages); }
  // Edita cliente con trazabilidad sin cambiar el id. Actor: ADMINISTRADOR o RECEPCIONISTA. Tecnica: detalle con campos cambiados.
  @CacheEvict(value="clientRows",allEntries=true)
  public RecordDtos.ClientResponse updateClient(UUID id, RecordDtos.UpdateClientRequest request, String actorId) { UserAccount actor=users.findById(UUID.fromString(actorId)).orElseThrow(() -> new ResponseStatusException(HttpStatus.UNAUTHORIZED)); ClientRecord client=clients.findById(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,"Client not found")); List<String> changed=new ArrayList<>(); String oldName=plainName(client); if (!oldName.equals(request.name().trim())) { var name=crypto.encrypt(request.name().trim()); client.updateName(name.value(),name.nonce()); changed.add("nombre"); } String docLookup=crypto.lookup(normalizeDocument(request.document())); boolean sameDoc=client.getIdentifications().stream().anyMatch(row -> docLookup.equals(row.getLookup())); if (!sameDoc) { client.clearIdentifications(); var document=crypto.encrypt(normalizeDocument(request.document())); try { client.addIdentification(RecordPolicy.OTHER_TYPE,docLookup,document.value(),document.nonce()); } catch (Exception duplicate) { throw new ResponseStatusException(HttpStatus.CONFLICT,"Client already exists"); } changed.add("documento"); } java.util.List<String> unique=normalizeContacts(request.contacts(),request.email()); if (unique.isEmpty()) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"At least one contact is required"); List<String> secondaryPhones=checkedPhones(request.secondaryContacts()); if (!sameContactValues(client,unique,secondaryPhones)) changed.add("contactos"); client.clearContacts(); storePrincipal(client,unique.get(0)); storeSecondaries(client,request.secondaryContacts()); UUID oldWorkshop=client.getWorkshop()==null?null:client.getWorkshop().getId(); Workshop next=resolveWorkshop(request.workshopId()); UUID nextWorkshop=next==null?null:next.getId(); if (!Objects.equals(oldWorkshop,nextWorkshop)) changed.add("taller"); client.setWorkshop(next); try { ClientRecord saved=clients.save(client); audit(saved,RecordPolicy.HISTORY_UPDATED,changed.isEmpty()?"Sin cambios":("Campos: "+String.join(", ",changed)),actor); return rows.one(saved); } catch (org.springframework.dao.DataIntegrityViolationException duplicate) { throw new ResponseStatusException(HttpStatus.CONFLICT,"Client already exists"); } }
  // Da de baja o reactiva con el catalogo global. Actor: RECEPCIONISTA o ADMINISTRADOR. Tecnica: valida ACTIVO o BAJA.
  @CacheEvict(value="clientRows",allEntries=true)
  public RecordDtos.ClientResponse changeClientStatus(UUID id, UUID statusId, String actorId) { UserAccount actor=users.findById(UUID.fromString(actorId)).orElseThrow(() -> new ResponseStatusException(HttpStatus.UNAUTHORIZED)); ClientRecord client=clients.findById(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,"Client not found")); WorkshopStatus status=statuses.findById(statusId).orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status")); boolean baja=mx.portaltransporte.workshops.WorkshopPolicy.INACTIVE_CODE.equals(status.getCode()); boolean activa=mx.portaltransporte.workshops.WorkshopPolicy.ACTIVE_CODE.equals(status.getCode()); if (!baja&&!activa) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status"); client.setStatus(status); ClientRecord saved=clients.save(client); audit(saved,baja?RecordPolicy.HISTORY_DEACTIVATED:RecordPolicy.HISTORY_REACTIVATED,"Estatus cambiado a "+status.getCode(),actor); return rows.one(saved); }
  // Asocia un vehiculo al cliente. Actor: ADMINISTRADOR o RECEPCIONISTA. Tecnica: evita vinculo activo duplicado.
  @CacheEvict(value="clientRows",allEntries=true)
  public RecordDtos.ClientVehicleResponse linkVehicle(UUID clientId, RecordDtos.LinkVehicleRequest request, String actorId) { UserAccount actor=users.findById(UUID.fromString(actorId)).orElseThrow(() -> new ResponseStatusException(HttpStatus.UNAUTHORIZED)); ClientRecord client=clients.findById(clientId).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,"Client not found")); Vehicle vehicle=vehicles.findById(request.vehicleId()).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,"Vehicle not found")); if (!RecordPolicy.VEHICLE_RELATIONSHIPS.contains(request.relationshipType())) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid relationship"); if (!mx.portaltransporte.workshops.WorkshopPolicy.ACTIVE_CODE.equals(client.getStatus().getCode())) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Client is not active"); if (links.findByVehicleIdAndEndsOnIsNull(request.vehicleId()).isPresent()) throw new ResponseStatusException(HttpStatus.CONFLICT,"Vehicle already linked"); ClientVehicle link=links.save(linkFactory.create(new ClientVehicleFactory.LinkParams(client,vehicle,request.relationshipType()))); audit(client,RecordPolicy.HISTORY_VEHICLE_LINKED,"Placa "+vehicle.getPlate()+" como "+request.relationshipType(),actor); return toVehicleResponse(link); }
  // Desvincula con fecha sin borrar historia. Actor: ADMINISTRADOR o RECEPCIONISTA. Tecnica: baja logica.
  @CacheEvict(value="clientRows",allEntries=true)
  public void unlinkVehicle(UUID clientId, UUID associationId, String actorId) { UserAccount actor=users.findById(UUID.fromString(actorId)).orElseThrow(() -> new ResponseStatusException(HttpStatus.UNAUTHORIZED)); ClientRecord client=clients.findById(clientId).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,"Client not found")); ClientVehicle link=links.findById(associationId).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,"Link not found")); if (!link.getClient().getId().equals(client.getId())) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Link not found"); if (link.isActive()) { link.endNow(); links.save(link); audit(client,RecordPolicy.HISTORY_VEHICLE_UNLINKED,"Placa "+link.getVehicle().getPlate()+" desvinculada",actor); } }
  // Vehiculos asociados activos. Actor: rol autorizado. Tecnica: la seccion aparece por default, vacia al inicio.
  @Transactional(readOnly=true) public List<RecordDtos.ClientVehicleResponse> listClientVehicles(UUID clientId) { if (!clients.existsById(clientId)) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Client not found"); return links.findByClientIdOrderByStartsOnDesc(clientId).stream().filter(ClientVehicle::isActive).map(this::toVehicleResponse).toList(); }
  // Historial de trazabilidad. Actor: ADMINISTRADOR o RECEPCIONISTA. Tecnica: orden nuevo a viejo.
  @Transactional(readOnly=true) public List<RecordDtos.ClientHistoryResponse> listClientHistory(UUID clientId) { if (!clients.existsById(clientId)) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Client not found"); return history.findByClientIdOrderByCreatedAtDesc(clientId).stream().map(row -> new RecordDtos.ClientHistoryResponse(row.getId(),row.getAction(),row.getDetail(),row.getActorName(),row.getCreatedAt())).toList(); }
  // Crea vehiculo unico por placa/vin. Actor: ADMINISTRADOR o RECEPCIONISTA. Tecnica: normaliza antes de validar duplicados.
  @Transactional(timeout=VehiclePolicy.UPLOAD_TIMEOUT_SECONDS)
  public UUID createVehicle(RecordDtos.CreateVehicleRequest request, List<MultipartFile> photos) { String plate=normalizeDocument(request.plate()); String vin=normalizeDocument(request.vin()); if(vehicles.existsByPlate(plate) || vehicles.existsByVin(vin)) throw new ResponseStatusException(HttpStatus.CONFLICT,"Vehicle already exists"); Vehicle vehicle=vehicles.save(vehicleFactory.create(new VehicleFactory.VehicleParams(plate,vin,request.brand().trim(),request.model().trim(),request.year().shortValue(),request.mileageKm()))); replaceVehiclePhotos(vehicle,photos); return vehicle.getId(); }
  // Lista vehiculos paginados por placa. Actor: rol autorizado en consulta. Tecnica: paginacion en BD (placa en claro).
  @Transactional(readOnly = true) public RecordDtos.VehiclePageResponse listVehicles(int page, int size) { if (page<RecordPolicy.CLIENT_PAGE_MIN) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid page"); if (size<1||size>RecordPolicy.CLIENT_PAGE_SIZE_MAX) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid size"); org.springframework.data.domain.Page<Vehicle> found=vehicles.findAll(org.springframework.data.domain.PageRequest.of(page-1,size,org.springframework.data.domain.Sort.by("plate"))); List<UUID> ids=found.getContent().stream().map(Vehicle::getId).toList(); List<ClientVehicle> activeLinks=ids.isEmpty()?List.of():links.findByVehicleIdInAndEndsOnIsNullOrderByStartsOnDesc(ids); Map<UUID,ClientVehicle> associations=activeLinks.stream().collect(java.util.stream.Collectors.toMap(link -> link.getVehicle().getId(),link -> link,(first,ignored) -> first)); List<RecordDtos.VehicleResponse> content=found.getContent().stream().map(vehicle -> toVehicleResponse(vehicle,associations.get(vehicle.getId()))).toList(); return new RecordDtos.VehiclePageResponse(content,page,size,found.getTotalElements(),found.getTotalPages()); }
  // Edita vehiculo existente. Actor: ADMINISTRADOR o RECEPCIONISTA. Tecnica: valida placa duplicada solo si cambia.
  @Transactional(timeout=VehiclePolicy.UPLOAD_TIMEOUT_SECONDS)
  public RecordDtos.VehicleResponse updateVehicle(UUID id, RecordDtos.UpdateVehicleRequest request, List<MultipartFile> photos) { Vehicle vehicle=vehicles.findById(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,"Vehicle not found")); String plate=normalizeDocument(request.plate()); String vin=normalizeDocument(request.vin()); if(!vehicle.getPlate().equals(plate) && vehicles.existsByPlate(plate)) throw new ResponseStatusException(HttpStatus.CONFLICT,"Vehicle already exists"); if(!vin.equals(vehicle.getVin()) && vehicles.existsByVin(vin)) throw new ResponseStatusException(HttpStatus.CONFLICT,"Vehicle already exists"); vehicle.updateDetails(plate,vin,request.brand().trim(),request.model().trim(),request.year().shortValue(),request.mileageKm()); Vehicle saved=vehicles.save(vehicle); replaceVehiclePhotos(saved,photos); return toVehicleResponse(saved,links.findByVehicleIdAndEndsOnIsNull(id).orElse(null)); }
  // Elimina vehiculo por id opaco. Actor: ADMINISTRADOR o RECEPCIONISTA. Tecnica: 404 si no existe.
  public void deleteVehicle(UUID id) { Vehicle vehicle=vehicles.findById(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,"Vehicle not found")); vehicles.delete(vehicle); }
  // Guarda hasta tres fotos y conserva las anteriores si no se enviaron nuevas. Actor: RECEPCIONISTA o ADMINISTRADOR.
  private void replaceVehiclePhotos(Vehicle vehicle, List<MultipartFile> photos) {
    List<MultipartFile> files=photos==null?List.of():photos.stream().filter(file -> file!=null&&!file.isEmpty()).toList();
    if(files.isEmpty()) return;
    if(files.size()>VehiclePolicy.MAX_PHOTOS) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Maximum three vehicle photos");
    for(MultipartFile file:files) {
      if(file.getSize()>VehiclePolicy.MAX_PHOTO_BYTES) throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Photo exceeds 15 MB");
      String mime=Objects.toString(file.getContentType(),"").toLowerCase(Locale.ROOT);
      if(!VehiclePolicy.ALLOWED_PHOTO_MIMES.contains(mime)) throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"Photo must be PNG, JPEG or WebP");
    }
    vehiclePhotos.deleteByVehicleId(vehicle.getId());
    for(int index=0;index<files.size();index++) {
      MultipartFile file=files.get(index);
      try {
        String name=Objects.toString(file.getOriginalFilename(),"foto").replaceAll("[^a-zA-Z0-9._-]","_");
        vehiclePhotos.save(vehiclePhotoFactory.create(new VehiclePhotoFactory.PhotoParams(vehicle,(short)(index+1),file.getBytes(),Objects.toString(file.getContentType(),"").toLowerCase(Locale.ROOT),name)));
      } catch(java.io.IOException exception) { throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unreadable photo"); }
    }
  }
  private RecordDtos.VehicleResponse toVehicleResponse(Vehicle vehicle, ClientVehicle association) {
    String clientName=null;
    if(association!=null) { try { clientName=crypto.decrypt(association.getClient().getNameCiphertext(),association.getClient().getNameNonce()); } catch(Exception ignored) { clientName="[protegido]"; } }
    return new RecordDtos.VehicleResponse(vehicle.getId(),vehicle.getPlate(),vehicle.getVin(),vehicle.getBrand(),vehicle.getModel(),vehicle.getYear(),vehicle.getMileageKm(),(int)vehiclePhotos.countByVehicleId(vehicle.getId()),association==null?null:association.getId(),association==null?null:association.getClient().getId(),clientName);
  }
  // Guarda el principal tipificado. Actor: sistema. Tecnica: EMAIL con @, PHONE en otro caso.
  private void storePrincipal(ClientRecord client, String principal) { String type=principal.contains("@")?RecordPolicy.CONTACT_EMAIL:RecordPolicy.CONTACT_PHONE; var cipher=crypto.encrypt(principal); client.addContact(type,crypto.lookup(principal),cipher.value(),cipher.nonce(),null,null,true); }
  // Guarda secundarios con nombre cifrado. Actor: sistema. Tecnica: valida celular exacto 400 si falla.
  private void storeSecondaries(ClientRecord client, java.util.List<RecordDtos.SecondaryContactDto> secondaries) { for (RecordDtos.SecondaryContactDto item : checkedSecondaries(secondaries)) { String phone=canonicalPhone(item.phone()); var value=crypto.encrypt(phone); var name=crypto.encrypt(item.name().trim()); client.addContact(RecordPolicy.CONTACT_PHONE,crypto.lookup(phone),value.value(),value.nonce(),name.value(),name.nonce(),false); } }
  // Valida secundarios y devuelve telefonos canonicos. Actor: sistema. Tecnica: misma regex que el frontend.
  private java.util.List<String> checkedPhones(java.util.List<RecordDtos.SecondaryContactDto> secondaries) { List<String> out=new ArrayList<>(); for (RecordDtos.SecondaryContactDto item : checkedSecondaries(secondaries)) out.add(canonicalPhone(item.phone())); return out; }
  private java.util.List<RecordDtos.SecondaryContactDto> checkedSecondaries(java.util.List<RecordDtos.SecondaryContactDto> secondaries) { if (secondaries==null) return List.of(); for (RecordDtos.SecondaryContactDto item : secondaries) { if (item==null||item.name()==null||item.name().trim().isEmpty()||item.phone()==null) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid secondary contact"); canonicalPhone(item.phone()); } return secondaries; }
  // Canoniza y valida el celular. Actor: sistema. Tecnica: quita espacios y guiones, exige 10 digitos con +52 opcional.
  private String canonicalPhone(String raw) { String phone=raw==null?"":raw.replaceAll("[\\s-]",""); if (!phone.matches(RecordPolicy.CELLPHONE_PATTERN)) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid cellphone"); return phone; }
  // Compara contactos actuales contra los nuevos. Actor: sistema. Tecnica: evita marcar edicion fantasma.
  private boolean sameContactValues(ClientRecord client, java.util.List<String> unique, java.util.List<String> secondaryPhones) { List<String> current=new ArrayList<>(); for (ClientContact contact : client.getContacts()) { try { current.add(crypto.decrypt(contact.getValueCiphertext(),contact.getValueNonce())); } catch (Exception failed) { current.add("[protegido]"); } } List<String> next=new ArrayList<>(unique); next.addAll(secondaryPhones); return new HashSet<>(current).equals(new HashSet<>(next))&&current.size()==next.size(); }
  private String plainName(ClientRecord client) { try { return crypto.decrypt(client.getNameCiphertext(),client.getNameNonce()); } catch (Exception failed) { return ""; } }
  private int contactCount(ClientRecord client) { return client.getContacts().size(); }
  // Normaliza identificadores. Actor: sistema. Tecnica: trim + mayusculas evita duplicados por formato.
  private String normalizeDocument(String value) { return value.trim().toUpperCase(Locale.ROOT); }
  // Normaliza N contactos a minusculas sin duplicados. Actor: sistema. Tecnica: misma regla que el alta.
  private java.util.List<String> normalizeContacts(java.util.List<String> contacts, String email) { java.util.List<String> raw=contacts==null||contacts.isEmpty() ? java.util.List.of(email) : contacts; java.util.LinkedHashSet<String> unique=new java.util.LinkedHashSet<>(); for (String item : raw) { if (item==null||item.isBlank()) continue; unique.add(item.trim().toLowerCase(Locale.ROOT)); } return new java.util.ArrayList<>(unique); }
  // Resuelve el taller activo o falla 400. Actor: sistema. Tecnica: null desasocia.
  private Workshop resolveWorkshop(UUID workshopId) { if (workshopId==null) return null; Workshop workshop=workshopRepo.findById(workshopId).orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,"Workshop not found")); if (!mx.portaltransporte.workshops.WorkshopPolicy.ACTIVE_CODE.equals(workshop.getStatus().getCode())) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Workshop is not active"); return workshop; }
  // Estatus ACTIVO del catalogo global. Actor: sistema. Tecnica: siembra perezosa idempotente.
  private WorkshopStatus activeStatus() { statuses.findByCode(mx.portaltransporte.workshops.WorkshopPolicy.ACTIVE_CODE).ifPresentOrElse(s -> {}, () -> statuses.save(statusFactory.create(new WorkshopStatusFactory.StatusParams(mx.portaltransporte.workshops.WorkshopPolicy.ACTIVE_CODE,"Activo")))); statuses.findByCode(mx.portaltransporte.workshops.WorkshopPolicy.INACTIVE_CODE).ifPresentOrElse(s -> {}, () -> statuses.save(statusFactory.create(new WorkshopStatusFactory.StatusParams(mx.portaltransporte.workshops.WorkshopPolicy.INACTIVE_CODE,"Baja")))); return statuses.findByCode(mx.portaltransporte.workshops.WorkshopPolicy.ACTIVE_CODE).orElseThrow(() -> new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR)); }
  // Audita sin cambiar el id. Actor: sistema. Tecnica: Factory Method con actor desnormalizado.
  private void audit(ClientRecord client, String action, String detail, UserAccount actor) { history.save(historyFactory.create(new ClientHistoryFactory.HistoryParams(client,action,detail,actor.getUsername()))); }
  // Convierte un vinculo a fila. Actor: sistema. Tecnica: datos del vehiculo en texto plano.
  private RecordDtos.ClientVehicleResponse toVehicleResponse(ClientVehicle link) { Vehicle v=link.getVehicle(); return new RecordDtos.ClientVehicleResponse(link.getId(),v.getId(),v.getPlate(),v.getBrand(),v.getModel(),v.getYear(),link.getRelationshipType(),link.getStartsOn()); }
}
